function validate([groups, elements]) {
  if (groups.length < 1 || groups.length > 100000) return 'groups needs 1 to 10^5 sizes.';
  if (elements.length < 1 || elements.length > 100000) return 'elements needs 1 to 10^5 values.';
  if (groups.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each group size is between 1 and 10^5.';
  if (elements.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each element is between 1 and 10^5.';
  return null;
}

