function assignElements(groups, elements) {
  const limit = Math.max(...groups);
  const owner = new Array(limit + 1).fill(-1);
  for (let j = 0; j < elements.length; j++) {
    const value = elements[j];
    if (value > limit || owner[value] !== -1) {
      continue;
    }
    for (let multiple = value; multiple <= limit; multiple += value) {
      if (owner[multiple] === -1) {
        owner[multiple] = j;
      }
    }
  }
  return groups.map(size => owner[size]);
}

