function generate(rand, size) {
  const int = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    // A product of small primes has many divisors, so many elements compete for it.
    const smooth = () => {
      let value = 1;
      for (;;) {
        const prime = [2, 3, 5, 7, 11, 13][int(0, 5)];
        if (value * prime > 100000) return value;
        value *= prime;
      }
    };
    const share = rand();
    const groups = Array.from({ length: 2000 }, () => rand() < 0.4 ? smooth() : int(1, 100000));
    const elements = Array.from({ length: 2000 }, () => rand() < share ? int(2, 200) : int(2, 100000));
    // Sometimes put a 1, which divides everything, somewhere in the list.
    if (rand() < 0.5) elements[int(0, 1999)] = 1;
    return [groups, elements];
  }
  const top = rand() < 0.7 ? 12 : 40;
  const groups = Array.from({ length: int(1, 6) }, () => int(1, top));
  const elements = Array.from({ length: int(1, 5) }, () => int(1, top));
  return [groups, elements];
}
